awaitPassingOn(condition, ready) { try { condition.await(); }       // await returns holding the lock
 catch(Interrupted e) { if(ready()) condition.signal(); throw e; } } // pass on a signal this waiter may have absorbed
close() {lock();try{closed=true;notFull.signalAll();notEmpty.signalAll();}finally{unlock();}}

