 while(count.get()==capacity && !closed) awaitPassingOn(notFull, ()=>count.get()<capacity);
 if(closed)throw Closed();
 tail.next=node(x);tail=tail.next;old=count.getAndIncrement();
 if(old+1<capacity)notFull.signal();
 } finally {putLock.unlock();}
